const localVue = getLocalVue();

/**
 * Mount GalaxyAI (as a panel unless `props` say otherwise) with its message
 * cells and input stubbed and a real chat store, once its initial loads settle.
 * Import GalaxyAI through this helper only, so the mocks above apply to it.
 */
export async function mountChat(props: Record<string, unknown> = {}) {
    const pinia = createPinia();
    setActivePinia(pinia);
    const wrapper = mount(GalaxyAI, {
        props: { panel: true, ...props },
        global: {
            ...withPlugins(localVue, pinia),
            stubs: { ...localVue.stubs, FontAwesomeIcon: true, BSkeleton: true },
        },
    });
    await flushPromises();
    return { wrapper, chatStore: useChatStore() };
}

/** The text of every message in the conversation, oldest first. */
export function messageTexts(wrapper: VueWrapper) {
    return wrapper.findAll(".chat-message-stub").map((message) => message.text());
}

/** Type `text` into the chat input, submit it, and let the request start. */
export async function sendMessage(wrapper: VueWrapper, text: string) {
    const input = wrapper.findComponent(ChatInputStub);
    input.vm.$emit("input", text);
    await nextTick();
    input.vm.$emit("submit");
    await flushPromises();
}

/** A successful `POST /api/chat` result. */
export function chatReply(response: string, exchangeId: string) {
    return { data: { response, exchange_id: exchangeId }, error: undefined };
}

import type { BaseWrapper } from "@vue/test-utils";
import flushPromises from "flush-promises";
import { createMemoryHistory, createRouter } from "vue-router";

const RouteStub = { render: () => null };

/**
 * A router with in-memory history for link components, matching each of `paths` and
 * served under `base` when given, so tests can check resolved hrefs and navigation
 * without touching `window.location`.
 */
export function createMemoryRouter({ paths = ["/", "/pages/create"], base }: { paths?: string[]; base?: string } = {}) {
    return createRouter({
        history: createMemoryHistory(base),
        routes: paths.map((path) => ({ path, component: RouteStub })),
    });
}

/**
 * Clicks the enabled confirm-footer button labelled `text` in a mounted GModal within
 * `wrapper`, then flushes promises. Unlike `vm.$emit("ok" | "cancel")`, this goes through
 * the native dialog, so GModal emits `ok` or `cancel` once, as it does for a user.
 */
export async function clickModalButton(wrapper: Pick<BaseWrapper<Node>, "findAll">, text: string) {
    const matches = wrapper.findAll(".g-modal-confirm-buttons button").filter((button) => button.text() === text);
    const [button] = matches;
    if (!button || matches.length > 1) {
        throw new Error(`expected one "${text}" modal button, found ${matches.length}`);
    }
    if (button.attributes("aria-disabled") === "true") {
        throw new Error(`the "${text}" modal button is disabled`);
    }
    await button.trigger("click");
    await flushPromises();
}

