/** Tool Shed's Category response model (tool_shed_client/schema/__init__.py). */
export interface ToolShedCategory {
    id: string;
    name: string;
    description: string;
    deleted: boolean;
    repositories: number;
}

export const TOOL_SHED_CATEGORIES: ToolShedCategory[] = [
    {
